import { Container } from '../../../components'
import PdfViewer from '../../../components/PdfViewer'
import { getQueryParams, isMobileView, getFileExtension } from '../../../helpers/utility'
import { IframePageStyle } from './index.style'

function IframePage () {
  const src = getQueryParams('src')
  const title = decodeURI(getQueryParams('title'))
  return (
    <Container
      title={title}
      displayBackButton
      hideBottomTabs
      showInnerHeader
    >
      <IframePageStyle>
        {
          isMobileView() && (getFileExtension(src) === 'pdf') ? (
            <PdfViewer pdf={src} />
          ) : (
            <iframe
              className='iframe'
              title={title}
              src={src}
            />
          )
        }
      </IframePageStyle>
    </Container>
  )
}

export default IframePage
