import { useCallback, useEffect, useRef } from 'react'
import { PDF_JS, PDF_VIEWER_JS, PDF_WORKER_JS } from './constants'
import { loadDynamicScript } from '../../helpers/loadDynamicScript'
import { PdfViewerStyle } from './index.style'
import PDFViewerApplication from './viewer'

function PdfViewer ({ className, pdf }) {
  const timerRef = useRef()
  const loadPdfFile = useCallback(() => {
    PDFViewerApplication.initUI()
    // The offsetParent is not set until the PDF.js iframe or object is visible;
    // waiting for first animation.
    const animationStarted = new Promise(function (resolve) {
      window.requestAnimationFrame(resolve)
    })

    // We need to delay opening until all HTML is loaded.
    animationStarted.then(function () {
      PDFViewerApplication.open({
        url: pdf
      })
    })
  }, [pdf])

  useEffect(() => {
    if (!(window.pdfjsLib && window.pdfjsViewer)) {
      loadDynamicScript(
        PDF_JS,
        'pdfJs',
        '',
        () => {
          if (window.pdfjsLib) {
            // pdfjsLib available globally
            window.pdfjsLib.GlobalWorkerOptions.workerSrc = PDF_WORKER_JS
            loadDynamicScript(PDF_VIEWER_JS, 'pdfViewerJs', '', () => {
              if (!timerRef.current) {
                timerRef.current = setInterval(() => {
                  if (window.pdfjsLib && window.pdfjsViewer) {
                    loadPdfFile()
                    clearInterval(timerRef.current)
                  }
                }, 50)
              }
            })
          }
        }
      )
    } else {
      loadPdfFile()
    }
  }, [loadPdfFile])

  return (
    <PdfViewerStyle className={className}>
      <div id='viewerContainer'>
        <div id='viewer' class='pdfViewer' />
      </div>

      <div id='loadingBar'>
        <div class='progress' />
        <div class='glimmer' />
      </div>
      <div id='errorWrapper' hidden='true'>
        <div id='errorMessageLeft'>
          <span id='errorMessage' />
        </div>
      </div>
      <footer>
        <button className='toolbarButton pageUp' title='Previous Page' id='previous'>
          <i className='arrow up' />
        </button>
        <button className='toolbarButton pageDown' title='Next Page' id='next'>
          <i class='arrow down' />
        </button>

        <input type='number' id='pageNumber' className='toolbarField pageNumber' value='1' size='4' min='1' />

        <button className='toolbarButton' title='Zoom Out' id='zoomOut'>
          <div className='circle'>
            <div className='zoomOut' />
          </div>
        </button>
        <button className='toolbarButton' title='Zoom In' id='zoomIn'>
          <div className='circle'>
            <div className='zoomIn' />
          </div>
        </button>
      </footer>
    </PdfViewerStyle>
  )
}

export default PdfViewer
